using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using RaceDay.API.Data; using RaceDay.API.DTOs; using RaceDay.API.Models;
namespace RaceDay.API.Controllers;
[ApiController,Route("api/events")]
public class EventsController(RaceDayContext db):ControllerBase
{
 [HttpGet] public async Task<IActionResult> List()=>Ok(await db.Events.Include(x=>x.Categories).OrderBy(x=>x.Date).ToListAsync());
 [HttpGet("{id:int}")] public async Task<IActionResult> Get(int id){var e=await db.Events.Include(x=>x.Categories).SingleOrDefaultAsync(x=>x.Id==id);return e is null?NotFound():Ok(e);}
 [HttpPost] public async Task<IActionResult> Create(EventRequest r){var uid=HttpContext.Session.GetInt32("UserId");if(uid is null)return Unauthorized();if(HttpContext.Session.GetString("Role")!="Organiser")return Forbid();if(r.EventType is not ("Run" or "Walk" or "Cycle"))return BadRequest(new{message="EventType must be Run, Walk or Cycle."});var e=new Event{Name=r.Name,Description=r.Description,Date=r.Date,Location=r.Location,DistanceKm=r.DistanceKm,EventType=r.EventType,OrganiserId=uid.Value};db.Events.Add(e);await db.SaveChangesAsync();return CreatedAtAction(nameof(Get),new{id=e.Id},e);}
 [HttpPut("{id:int}")] public async Task<IActionResult> Update(int id,EventRequest r){var uid=HttpContext.Session.GetInt32("UserId");if(uid is null)return Unauthorized();if(HttpContext.Session.GetString("Role")!="Organiser")return Forbid();var e=await db.Events.FindAsync(id);if(e is null)return NotFound();if(e.OrganiserId!=uid)return Forbid();if(r.EventType is not ("Run" or "Walk" or "Cycle"))return BadRequest(new{message="EventType must be Run, Walk or Cycle."});e.Name=r.Name;e.Description=r.Description;e.Date=r.Date;e.Location=r.Location;e.DistanceKm=r.DistanceKm;e.EventType=r.EventType;await db.SaveChangesAsync();return Ok(e);}
 [HttpDelete("{id:int}")] public async Task<IActionResult> Delete(int id){var uid=HttpContext.Session.GetInt32("UserId");if(uid is null)return Unauthorized();if(HttpContext.Session.GetString("Role")!="Organiser")return Forbid();var e=await db.Events.FindAsync(id);if(e is null)return NotFound();if(e.OrganiserId!=uid)return Forbid();db.Events.Remove(e);await db.SaveChangesAsync();return NoContent();}
 [HttpGet("{eventId:int}/categories")] public async Task<IActionResult> Categories(int eventId){if(!await db.Events.AnyAsync(x=>x.Id==eventId))return NotFound();return Ok(await db.Categories.Where(x=>x.EventId==eventId).ToListAsync());}
 [HttpPost("{eventId:int}/categories")] public async Task<IActionResult> AddCategory(int eventId,CategoryRequest r){var uid=HttpContext.Session.GetInt32("UserId");if(uid is null)return Unauthorized();if(HttpContext.Session.GetString("Role")!="Organiser")return Forbid();var e=await db.Events.FindAsync(eventId);if(e is null)return NotFound();if(e.OrganiserId!=uid)return Forbid();var c=new Category{EventId=eventId,Name=r.Name,Criteria=r.Criteria};db.Categories.Add(c);await db.SaveChangesAsync();return Created($"/api/events/{eventId}/categories",c);}
}
